<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: #f4f5f7;
    color: #172b4d;
    min-height: 100vh;
    padding: 24px 16px 48px;
  }
  h1 {
    text-align: center;
    margin-bottom: 18px;
    font-weight: 600;
    font-size: 22px;
    color: #172b4d;
  }
  .toolbar {
    display: flex;
    gap: 8px;
    justify-content: center;
    margin-bottom: 24px;
    flex-wrap: wrap;
  }
  #new-card {
    flex: 0 1 360px;
    padding: 10px 14px;
    border: 1px solid #dfe1e6;
    border-radius: 6px;
    font-size: 14px;
    outline: none;
    background: #fff;
    transition: border-color .15s, box-shadow .15s;
  }
  #new-card:focus {
    border-color: #4c9aff;
    box-shadow: 0 0 0 3px rgba(76,154,255,.2);
  }
  #add-card {
    padding: 10px 18px;
    background: #0052cc;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: background .15s;
  }
  #add-card:hover { background: #0747a6; }
  #add-card:active { background: #092c66; }

  .board {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 16px;
    max-width: 1200px;
    margin: 0 auto;
  }
  @media (max-width: 720px) {
    .board { grid-template-columns: 1fr; }
  }

  .column {
    background: #ebecf0;
    border-radius: 8px;
    padding: 12px;
    min-height: 420px;
    display: flex;
    flex-direction: column;
    transition: background .15s, outline .15s;
    outline: 2px solid transparent;
  }
  .column.drag-over {
    background: #dfe1e6;
    outline: 2px dashed #4c9aff;
  }

  .col-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 6px 6px 12px;
    font-weight: 700;
    font-size: 12px;
    color: #5e6c84;
    text-transform: uppercase;
    letter-spacing: .06em;
  }
  .count {
    background: #b3bac5;
    color: #172b4d;
    border-radius: 999px;
    padding: 2px 9px;
    font-size: 12px;
    font-weight: 700;
    min-width: 24px;
    text-align: center;
  }

  .cards {
    display: flex;
    flex-direction: column;
    gap: 8px;
    flex: 1;
  }

  .card {
    background: #fff;
    border-radius: 6px;
    padding: 12px;
    box-shadow: 0 1px 2px rgba(9,30,66,.15);
    cursor: grab;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 8px;
    transition: box-shadow .15s, transform .08s;
    font-size: 14px;
    line-height: 1.4;
    color: #172b4d;
    user-select: none;
  }
  .card:hover { box-shadow: 0 4px 8px rgba(9,30,66,.18); }
  .card:active { cursor: grabbing; }
  .card.dragging { opacity: .45; }

  .card-title {
    flex: 1;
    word-break: break-word;
    white-space: pre-wrap;
  }

  .card-del {
    background: transparent;
    border: none;
    color: #6b778c;
    cursor: pointer;
    font-size: 18px;
    line-height: 1;
    padding: 0 6px;
    border-radius: 4px;
    flex-shrink: 0;
    transition: background .15s, color .15s;
  }
  .card-del:hover { background: #ffebe6; color: #de350b; }
</style>
</head>
<body>
  <h1>Kanban Board</h1>

  <div class="toolbar">
    <input type="text" id="new-card" placeholder="New card title…" autocomplete="off" />
    <button id="add-card" type="button">Add Card</button>
  </div>

  <div class="board">
    <div class="column" id="col-todo" data-col="todo">
      <div class="col-header"><span>To Do</span><span class="count">0</span></div>
      <div class="cards"></div>
    </div>
    <div class="column" id="col-doing" data-col="doing">
      <div class="col-header"><span>Doing</span><span class="count">0</span></div>
      <div class="cards"></div>
    </div>
    <div class="column" id="col-done" data-col="done">
      <div class="col-header"><span>Done</span><span class="count">0</span></div>
      <div class="cards"></div>
    </div>
  </div>

<script>
(function () {
  const STORAGE_KEY = "kanban-board-v1";
  const COLS = ["todo", "doing", "done"];

  // Load state, defaulting to empty columns
  let raw = {};
  try { raw = JSON.parse(localStorage.getItem(STORAGE_KEY) || "{}") || {}; }
  catch (e) { raw = {}; }
  const state = {};
  COLS.forEach(function (c) {
    state[c] = Array.isArray(raw[c]) ? raw[c].filter(function (x) {
      return x && typeof x.id === "string" && typeof x.title === "string";
    }) : [];
  });

  const $ = function (sel, root) { return (root || document).querySelector(sel); };
  const input = $("#new-card");
  const addBtn = $("#add-card");

  function uid() {
    return "c_" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function save() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); }
    catch (e) { /* quota / privacy mode — ignore */ }
  }

  function updateCounts() {
    COLS.forEach(function (c) {
      const col = document.getElementById("col-" + c);
      const countEl = col.querySelector(".count");
      countEl.textContent = String(state[c].length);
    });
  }

  function makeCardEl(card) {
    const el = document.createElement("div");
    el.className = "card";
    el.draggable = true;
    el.dataset.id = card.id;

    const title = document.createElement("span");
    title.className = "card-title";
    title.textContent = card.title;
    el.appendChild(title);

    const del = document.createElement("button");
    del.className = "card-del";
    del.type = "button";
    del.setAttribute("aria-label", "Delete card");
    del.title = "Delete card";
    del.textContent = "\u00D7"; // ×
    del.addEventListener("click", function (ev) {
      ev.stopPropagation();
      deleteCard(card.id);
    });
    el.appendChild(del);

    el.addEventListener("dragstart", function (ev) {
      el.classList.add("dragging");
      ev.dataTransfer.setData("text/plain", card.id);
      ev.dataTransfer.effectAllowed = "move";
    });
    el.addEventListener("dragend", function () {
      el.classList.remove("dragging");
    });

    return el;
  }

  function render() {
    COLS.forEach(function (c) {
      const col = document.getElementById("col-" + c);
      const container = col.querySelector(".cards");
      container.innerHTML = "";
      state[c].forEach(function (card) {
        container.appendChild(makeCardEl(card));
      });
    });
    updateCounts();
  }

  function addCard(text) {
    const t = String(text || "").trim();
    if (!t) return false;
    state.todo.push({ id: uid(), title: t });
    save();
    render();
    return true;
  }

  function deleteCard(id) {
    for (let i = 0; i < COLS.length; i++) {
      const c = COLS[i];
      const idx = state[c].findIndex(function (x) { return x.id === id; });
      if (idx !== -1) {
        state[c].splice(idx, 1);
        save();
        render();
        return;
      }
    }
  }

  function moveCard(id, targetCol) {
    if (COLS.indexOf(targetCol) === -1) return;
    for (let i = 0; i < COLS.length; i++) {
      const c = COLS[i];
      const idx = state[c].findIndex(function (x) { return x.id === id; });
      if (idx !== -1) {
        if (c === targetCol) return; // already in the target column
        const card = state[c].splice(idx, 1)[0];
        state[targetCol].push(card);
        save();
        render();
        return;
      }
    }
  }

  // Wire up drag & drop on each column
  COLS.forEach(function (c) {
    const col = document.getElementById("col-" + c);

    col.addEventListener("dragover", function (ev) {
      ev.preventDefault(); // required to allow drop
      ev.dataTransfer.dropEffect = "move";
      if (!col.classList.contains("drag-over")) col.classList.add("drag-over");
    });

    col.addEventListener("dragleave", function (ev) {
      // Only clear highlight when leaving the column itself
      if (!col.contains(ev.relatedTarget)) {
        col.classList.remove("drag-over");
      }
    });

    col.addEventListener("drop", function (ev) {
      ev.preventDefault();
      col.classList.remove("drag-over");
      const id = ev.dataTransfer.getData("text/plain");
      if (id) moveCard(id, c);
    });
  });

  // Add-card controls
  function doAdd() {
    if (addCard(input.value)) {
      input.value = "";
      input.focus();
    }
  }
  addBtn.addEventListener("click", doAdd);
  input.addEventListener("keydown", function (ev) {
    if (ev.key === "Enter") {
      ev.preventDefault();
      doAdd();
    }
  });

  render();
})();
</script>
</body>
</html>
